  async function loadCartella(pazienteId: string): Promise<void> {
    const sessionEpoch = patientNavigationSequenceRef.current;
    try {
      const res = await fetch(`${API_URL}/patients/${pazienteId}/cartella`, {
        headers: operatorHeaders(),
      });
      if (!res.ok) return;
      const json = (await res.json()) as { patientId: string; data: CartellaPaziente | null };
      if (sessionEpoch !== patientNavigationSequenceRef.current) return;
      if (json.data) {
        setCartelle((prev) => {
          const idx = prev.findIndex((c) => c.pazienteId === pazienteId);
          const base = createDefaultCartella(pazienteId);
          const baseRec = base as unknown as Record<string, unknown>;
          const merged = { ...base, ...json.data, pazienteId } as unknown as Record<
            string,
            unknown
          >;
          // Defensive: a clinical-list field stored as a non-array (e.g. an object written by an
          // older import) must never reach the UI — coerce it back to the default array so
          // `.filter`/`.map` never crash the patient record.
          for (const k of Object.keys(baseRec)) {
            if (Array.isArray(baseRec[k]) && !Array.isArray(merged[k])) merged[k] = baseRec[k];
          }
          const safe = merged as unknown as CartellaPaziente;
          if (idx >= 0) return prev.map((c, i) => (i === idx ? safe : c));
          return [...prev, safe];
        });
      }
    } catch {
      if (sessionEpoch === patientNavigationSequenceRef.current) {
        showToast('Impossibile caricare la cartella clinica');
      }
    }
  }

  async function updateCartella(
    pazienteId: string,
    updates: Partial<CartellaPaziente>,
    options?: { optimistic?: boolean },
  ): Promise<boolean> {
    const documentSaveEpoch = sessionEpochRef.current;
    const existing =
      cartelle.find((c) => c.pazienteId === pazienteId) ?? createDefaultCartella(pazienteId);
    const updated = mergeCartellaPatch(existing, existing, updates);
    let saveError = 'Impossibile salvare i dati';

    // Optimistic update
    const applyUpdate = () =>
      setCartelle((prev) => {
        const idx = prev.findIndex((c) => c.pazienteId === pazienteId);
        return idx >= 0
          ? prev.map((c, i) => (i === idx ? mergeCartellaPatch(c, existing, updates) : c))
          : [...prev, updated];
      });
    if (options?.optimistic !== false) applyUpdate();

    // Persist to backend; return success so callers (e.g. inline edit) can react to failure.
    const headers = { 'Content-Type': 'application/json', ...operatorHeaders() };
    try {
      const ok = await cartellaWrites.current.enqueue(
        `${documentSaveEpoch}:${pazienteId}`,
        existing,
        updates,
        async (snapshot) => {
          if (documentSaveEpoch !== sessionEpochRef.current) return false;
          const data = cartellaWriteData(snapshot);
          const response = await fetch(`${API_URL}/patients/${pazienteId}/cartella`, {
            method: 'PUT',
            headers,
            body: JSON.stringify({ data }),
          });
          if (!response.ok) {
            const failure = await response.json().catch(() => null);
            if (failure?.code === 'tinetti_legacy_read_only') saveError = 'Lo storico Tinetti è di sola lettura. I campi inseriti sono conservati; ricarica lo storico prima di riprovare.';
          }
          return response.ok && documentSaveEpoch === sessionEpochRef.current;
        },
        mergeCartellaPatch,
      );
      if (documentSaveEpoch !== sessionEpochRef.current) return false;
      if (ok) {
        if (options?.optimistic === false) applyUpdate();
        showToast('Dati salvati correttamente');
        return true;
      }
      showToast(saveError);
      return false;
    } catch {
      if (documentSaveEpoch !== sessionEpochRef.current) return false;
      showToast('Impossibile salvare i dati');
      return false;
    }
  }

  // ── Issue #128: sincronizza l'assegnazione camera reale (letti/PatientRoomAssignment) ──
  // La cartella (JSON) conserva solo cameraNumero/lettoNumero visuali: l'occupazione
  // vera vive nelle assegnazioni letto. Senza questa sync la camera restava "libera".
  async function syncCameraAssignment(
    pazienteId: string,
    cameraNumero?: string,
    bedId?: string,
  ): Promise<{ ok: boolean; lettoLabel?: string }> {
    try {
      const today = localIsoDate();
      const assignRes = await fetch(
        `${API_URL}/patients/${pazienteId}/room-assignments?scope=active`,
        {
          headers: operatorHeaders(),
        },
      );
      const assignments: Array<{ id: string; bedId: string; endDate: string | null }> = assignRes.ok
        ? await assignRes.json()
        : [];
      if (!assignRes.ok) {
        showToast('Impossibile verificare l’assegnazione attuale');
        return { ok: false };
      }
      const active = assignments.find((a) => a.endDate === null || a.endDate >= today);

      // Camera rimossa → chiudi l'assegnazione attiva
      if (!cameraNumero) {
        if (active) {
          await fetch(`${API_URL}/patients/${pazienteId}/room-assignments/${active.id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json', ...operatorHeaders() },
            body: JSON.stringify({ endDate: today }),
          });
          void loadCamere(true, pazienteId);
        }
        return { ok: true };
      }

      // The patient detail owns a scoped room snapshot that exposes availability without
      // revealing the identities assigned to other beds.
      const room = camere.find((candidate) => candidate.numero === cameraNumero);
      if (!room) {
        showToast(`Camera ${cameraNumero} non trovata`);
        return { ok: false };
      }

      const isFree = (bed: Camera['letti'][number]) =>
        bed.stato !== 'manutenzione' && (bed.stato === 'libero' || bed.pazienteId === pazienteId);
      if (!bedId) {
        showToast('Seleziona un letto per completare l’assegnazione');
        return { ok: false };
      }
      const bed = room.letti.find((candidate) => candidate.id === bedId);
      if (bed && !isFree(bed)) {
        showToast(`Il letto selezionato nella camera ${cameraNumero} non è più disponibile`);
        return { ok: false };
      }
      if (!bed) {
        showToast('Il letto selezionato non appartiene alla camera indicata');
        return { ok: false };
      }

      if (active && active.bedId === bed.id) {
        return {
          ok: true,
          lettoLabel: bed.label ?? 'ABCDEFGH'[bed.numero - 1] ?? String(bed.numero),
        };
      }

      const assignmentUrl = active
        ? `${API_URL}/patients/${pazienteId}/room-assignments/${active.id}`
        : `${API_URL}/patients/${pazienteId}/room-assignments`;
      const res = await fetch(assignmentUrl, {
        method: active ? 'PUT' : 'POST',
        headers: { 'Content-Type': 'application/json', ...operatorHeaders() },
        body: JSON.stringify(active ? { bedId: bed.id } : { bedId: bed.id, startDate: today }),
      });
      if (!res.ok) {
        const err = (await res.json().catch(() => null)) as { error?: string } | null;
        showToast(err?.error ?? 'Impossibile assegnare la camera');
        if (res.status === 409) void loadCamere(true, pazienteId);
        return { ok: false };
      }
      void loadCamere(true, pazienteId);
      return {
        ok: true,
        lettoLabel: bed.label ?? 'ABCDEFGH'[bed.numero - 1] ?? String(bed.numero),
      };
    } catch {
      showToast('Impossibile assegnare la camera');
      return { ok: false };
    }
  }

