import { useEffect, useMemo, useRef, useState } from 'react';
import type { CartellaPaziente, Paziente } from '../../types';
import { API_URL } from '../../config';
import { operatorHeaders } from '../../lib/operatorSession';
import { facilityLocalMinute } from '../../lib/facilityTime';
import { loadPatientParameterTrends } from '../../lib/loadPatientParameterTrends';
import type { PatientParameterReading } from '../../lib/patientParameterReadings';
import { parameterPeriod, type ParameterPeriodPreset } from '../../lib/patientParameterWorkspace';
import type { TrendPeriod } from '../../lib/patientParameterTrends';
import { VitalSignsEditor } from './PatientDetailLazyTabs';
import { PatientParameterHistory } from './PatientParameterHistory';
import { PatientParameterTrends } from './PatientParameterTrends';
import { PatientParameterPeriodFilter } from './PatientParameterPeriodFilter';
import { PatientParameterEntry } from './PatientParameterEntry';
import './PatientParameterWorkspace.css';

interface Props {
  cartella: CartellaPaziente;
  paziente: Paziente;
  operatoreNome: string;
  operatoreId: string;
  onUpdate: (updates: Partial<CartellaPaziente>) => void;
}
export function PatientVitalSignsView(props: Props) {
  return <PatientParameterWorkspace key={`${props.paziente.id}:${props.operatoreId}`} {...props} />;
}
function PatientParameterWorkspace({
  cartella,
  paziente,
  operatoreNome,
  operatoreId,
  onUpdate,
}: Props) {
  const [today, setToday] = useState(() => facilityLocalMinute().slice(0, 10));
  const [preset, setPreset] = useState<ParameterPeriodPreset | 'custom'>('today');
  const [custom, setCustom] = useState<TrendPeriod>(() => parameterPeriod('today'));
  const period = useMemo(
    () => (preset === 'custom' ? custom : parameterPeriod(preset, today)),
    [preset, custom, today],
  );
  const [showGraph, setShowGraph] = useState(false);
  const [editLegacy, setEditLegacy] = useState(false);
  const [revision, setRevision] = useState(0);
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState<{
    key: string;
    readings?: PatientParameterReading[];
    error?: string;
  } | null>(null);
  const generation = useRef(0);
  const requestKey = `${paziente.id}:${operatoreId}:${period.start}:${period.end}:${revision}`;
  useEffect(() => {
    const controller = new AbortController();
    const version = ++generation.current;
    setResult(null);
    setProgress(0);
    void loadPatientParameterTrends(API_URL, paziente.id, period, {
      headers: operatorHeaders(),
      signal: controller.signal,
      onProgress: (count) => {
        if (!controller.signal.aborted && version === generation.current) setProgress(count);
      },
    })
      .then((readings) => {
        if (!controller.signal.aborted && version === generation.current)
          setResult({ key: requestKey, readings });
      })
      .catch(() => {
        if (!controller.signal.aborted && version === generation.current)
          setResult({
            key: requestKey,
            error:
              'Impossibile caricare tutte le rilevazioni del periodo. Riprova o scegli un intervallo più breve.',
          });
      });
    return () => controller.abort();
  }, [paziente.id, period, requestKey]);
  const current = result?.key === requestKey ? result : null;
  const readings = current?.readings;
  const refresh = () => setRevision((value) => value + 1);
  const showToday = () => {
    setToday(facilityLocalMinute().slice(0, 10));
    setPreset('today');
  };
  return (
    <div className="patient-vital-signs parameter-workspace" id="vital-panel">
      <PatientParameterEntry
        patientId={paziente.id}
        operatorId={operatoreId}
        onSaved={refresh}
        onDayChange={setToday}
        onShowToday={showToday}
      />
      <section className="parameter-workspace-records" aria-label="Consultazione parametri vitali">
        <div className="parameter-workspace-records__heading">
          <h3>Valori e andamento</h3>
          <button type="button" className="btn-secondary btn-sm" onClick={refresh}>
            Aggiorna
          </button>
        </div>
        <PatientParameterPeriodFilter
          preset={preset}
          period={period}
          onPreset={setPreset}
          onCustom={(value) => {
            setCustom(value);
            setPreset('custom');
          }}
        />
        <div className="parameter-workspace-summary">
          <div>
            <strong>
              {period.start.split('-').reverse().join('/')} –{' '}
              {period.end.split('-').reverse().join('/')}
            </strong>
            {readings && (
              <span>
                {readings.length} {readings.length === 1 ? 'rilevazione' : 'rilevazioni'} nel
                periodo
              </span>
            )}
          </div>
          <button
            type="button"
            className={`btn-secondary btn-sm${showGraph ? ' parameter-workspace-graph-active' : ''}`}
            aria-expanded={showGraph}
            aria-controls="parameter-inline-graph"
            onClick={() => setShowGraph((value) => !value)}
          >
            {showGraph ? 'Nascondi andamento' : 'Mostra andamento'}
          </button>
        </div>
        {!current && (
          <p role="status">
            Caricamento delle rilevazioni del periodo…{progress > 0 ? ` ${progress} lette` : ''}
          </p>
        )}
        {current?.error && (
          <div role="alert" className="parameter-trends-error">
            <p>{current.error}</p>
            <button type="button" className="btn-secondary btn-sm" onClick={refresh}>
              Riprova
            </button>
          </div>
        )}
        <div id="parameter-inline-graph" hidden={!showGraph}>
          {showGraph && readings && (
            <PatientParameterTrends readings={readings} period={period} sourceKey={requestKey} />
          )}
        </div>
        {readings && (
          <PatientParameterHistory
            key={requestKey}
            readings={readings}
            period={period}
            cartella={cartella}
          >
            <details onToggle={(event) => setEditLegacy(event.currentTarget.open)}>
              <summary>Modifica griglia di origine</summary>
              {editLegacy && (
                <VitalSignsEditor
                  mode="patient-chart"
                  cartella={cartella}
                  paziente={paziente}
                  onUpdate={onUpdate}
                  operatoreNome={operatoreNome}
                  value={undefined as never}
                  onChange={() => {}}
                />
              )}
            </details>
          </PatientParameterHistory>
        )}
      </section>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import type { DocumentoConsegnato, StatoDocumento, TipoDocumento } from '../../../types';
import { localIsoDate } from '../../../lib/appointmentRange';
import { documentAuthHeaders } from '../../../lib/entraAuth';
import {
  ARCHIVE_CATEGORIES,
  DOCUMENT_TYPE_LABELS,
  type ArchiveEntry,
} from '../../../lib/patientDocumentArchive';
import {
  classifyArchiveDocument,
  DOCUMENT_ACCEPT,
  saveArchiveEntry,
  uploadArchiveDocument,
  validateArchiveFile,
} from '../../../lib/patientDocumentArchiveIO';
import type { PatientDocumentMeta } from '../../../lib/patientDocumentsPage';
import { PatientArchivePreview } from './PatientArchivePreview';
import { CameraCapture } from '../../shared/CameraCapture';

export const DOCUMENT_STATUS_LABELS: Record<StatoDocumento, string> = {
  ricevuto: 'Ricevuto',
  mancante: 'Mancante',
  da_verificare: 'Da verificare',
  firmato: 'Firmato',
  scaduto: 'Scaduto',
};

export function ArchiveDocumentForm({
  initial,
  defaultType,
  records,
  patientId,
  operatorId,
  operatorRole,
  operatorName,
  onPersist,
  onStored,
  onClose,
}: {
  initial: ArchiveEntry | null;
  defaultType?: TipoDocumento;
  records: DocumentoConsegnato[];
  patientId: string;
  operatorId?: string;
  operatorRole?: string;
  operatorName: string;
  onPersist: (records: DocumentoConsegnato[]) => void | Promise<boolean>;
  onStored: (document: PatientDocumentMeta) => void;
  onClose: () => void;
}) {
  const [form, setForm] = useState<DocumentoConsegnato>(() => ({
    id: initial?.record?.id ?? crypto.randomUUID(),
    tipo:
      (initial?.type ?? defaultType) === 'patient_assessment'
        ? 'documento_identita'
        : (initial?.type ?? defaultType ?? 'documento_identita'),
    descrizione: initial?.record?.descrizione ?? '',
    dataConsegna: initial?.date ?? localIsoDate(),
    stato: initial?.record?.stato ?? 'ricevuto',
    firmatoDA: initial?.record?.firmatoDA ?? 'non_firmato',
    operatore: operatorName,
    note: initial?.record?.note ?? '',
    provenienza: initial?.record?.provenienza ?? '',
    scadenza: initial?.record?.scadenza ?? '',
    archiviato: initial?.archived,
    patientDocumentId: initial?.record?.patientDocumentId ?? initial?.document?.id,
  }));
  const [file, setFile] = useState<File | null>(null);
  const [stored, setStored] = useState(initial?.document ?? null);
  const storedRef = useRef(stored);
  const controllerRef = useRef<AbortController | null>(null);
  const busyRef = useRef(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [preview, setPreview] = useState(false);
  const [cameraOpen, setCameraOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  useEffect(() => () => controllerRef.current?.abort(), []);
  function selectFile(selected: File) {
    if (busyRef.current || storedRef.current) return;
    const validation = validateArchiveFile(selected);
    if (validation) {
      setError(validation);
      return;
    }
    setError('');
    setFile(selected);
    setPreview(true);
  }
  const set = (patch: Partial<DocumentoConsegnato>) =>
    setForm((current) => ({ ...current, ...patch }));
  const validDate = (value: string) =>
    /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(value)) &&
    new Date(value).toISOString().slice(0, 10) === value;
  async function save() {
    if (busyRef.current) return;
    if (!validDate(form.dataConsegna) || (form.scadenza && !validDate(form.scadenza))) {
      setError('Verifica le date del documento.');
      return;
    }
    if (!initial && !file && !storedRef.current && form.stato !== 'mancante') {
      setError('Seleziona il file da archiviare oppure indica il documento come mancante.');
      return;
    }
    busyRef.current = true;
    setSaving(true);
    setError('');
    const controller = new AbortController();
    controllerRef.current = controller;
    const scope = {
      patientId,
      signal: controller.signal,
      getHeaders: () => documentAuthHeaders(patientId, operatorId, operatorRole),
    };
    try {
      await saveArchiveEntry(
        {
          record: {
            ...form,
            descrizione: form.descrizione.trim() || DOCUMENT_TYPE_LABELS[form.tipo],
          },
          records,
          file,
          stored: storedRef.current,
          signal: controller.signal,
        },
        {
          upload: (selected, type) => uploadArchiveDocument(scope, selected, type),
          classify: (id, type) => classifyArchiveDocument(scope, id, type),
          remember: (document) => {
            storedRef.current = document;
            setStored(document);
            setFile(null);
            onStored(document);
          },
          persist: onPersist,
        },
      );
      if (!controller.signal.aborted) onClose();
    } catch (reason) {
      if (!controller.signal.aborted)
        setError(reason instanceof Error ? reason.message : 'Salvataggio non riuscito. Riprova.');
    } finally {
      busyRef.current = false;
      if (!controller.signal.aborted) setSaving(false);
    }
  }
  return (
    <div className="cr-inline-form patient-archive-form">
      <h3>{initial ? 'Modifica documento' : 'Nuovo documento'}</h3>
      <fieldset disabled={saving}>
        <div className="form-row-2col">
          <label>
            Tipo documento
            <select
              className="form-input"
              value={form.tipo}
              onChange={(event) => set({ tipo: event.target.value as TipoDocumento })}
            >
              {ARCHIVE_CATEGORIES.filter((category) => category.id !== 'valutazioni').map(
                (category) => (
                  <optgroup label={category.label} key={category.id}>
                    {category.types.map((type) => (
                      <option value={type} key={type}>
                        {DOCUMENT_TYPE_LABELS[type]}
                      </option>
                    ))}
                  </optgroup>
                ),
              )}
            </select>
          </label>
          <label>
            Stato
            <select
              className="form-input"
              value={form.stato}
              onChange={(event) => set({ stato: event.target.value as StatoDocumento })}
            >
              {Object.entries(DOCUMENT_STATUS_LABELS).map(([value, label]) => (
                <option value={value} key={value}>
                  {label}
                </option>
              ))}
            </select>
          </label>
          <label>
            Data ricezione
            <input
              className="form-input"
              type="date"
              value={form.dataConsegna}
              onChange={(event) => set({ dataConsegna: event.target.value })}
            />
          </label>
          <label>
            Scadenza
            <input
              className="form-input"
              type="date"
              value={form.scadenza}
              onChange={(event) => set({ scadenza: event.target.value })}
            />
          </label>
          <label>
            Provenienza
            <input
              className="form-input"
              maxLength={200}
              value={form.provenienza}
              onChange={(event) => set({ provenienza: event.target.value })}
              placeholder="Paziente, familiare, centro medico…"
            />
          </label>
          <label>
            Firmato da
            <select
              className="form-input"
              value={form.firmatoDA}
              onChange={(event) => set({ firmatoDA: event.target.value })}
            >
              <option value="non_firmato">Non firmato</option>
              <option value="paziente">Paziente</option>
              <option value="tutore">Tutore</option>
              <option value="familiare">Familiare</option>
              <option value="medico">Medico</option>
            </select>
          </label>
        </div>
        <label>
          Descrizione
          <input
            className="form-input"
            maxLength={200}
            value={form.descrizione}
            onChange={(event) => set({ descrizione: event.target.value })}
            placeholder={DOCUMENT_TYPE_LABELS[form.tipo]}
          />
        </label>
        <label>
          Note
          <textarea
            className="form-input"
            maxLength={2000}
            value={form.note}
            onChange={(event) => set({ note: event.target.value })}
            rows={2}
          />
        </label>
        <div className="patient-archive-form__file">
          {stored ? (
            <>
              <strong>File archiviato</strong>
              <span>{stored.originalName}</span>
            </>
          ) : (
            <div className="patient-archive-form__upload">
              <p>Allegato · PDF, JPEG, JPG o PNG, massimo 15 MB</p>
              <input
                ref={fileInputRef}
                type="file"
                accept={DOCUMENT_ACCEPT}
                aria-label="Seleziona documento"
                hidden
                onChange={(event) => {
                  const selected = event.target.files?.[0];
                  event.target.value = '';
                  if (selected) selectFile(selected);
                }}
              />
              <div className="patient-archive-form__upload-actions">
                <button
                  type="button"
                  className="btn-primary btn-sm"
                  onClick={() => fileInputRef.current?.click()}
                >
                  Carica file
                </button>
                <button
                  type="button"
                  className="btn-secondary btn-sm"
                  onClick={() => setCameraOpen(true)}
                >
                  Scatta foto
                </button>
              </div>
            </div>
          )}
          {(file || stored) && (
            <button type="button" className="btn-secondary btn-sm" onClick={() => setPreview(true)}>
              Anteprima{file ? ` · ${file.name}` : ''}
            </button>
          )}
        </div>
      </fieldset>
      {error && (
        <p role="alert" className="patient-archive__error">
          {error}
        </p>
      )}
      <div className="cr-inline-form__actions">
        <button type="button" className="btn-secondary btn-sm" disabled={saving} onClick={onClose}>
          Annulla
        </button>
        <button
          type="button"
          className="btn-success btn-sm"
          disabled={saving}
          onClick={() => void save()}
        >
          {saving ? 'Salvataggio…' : 'Salva documento'}
        </button>
      </div>
      {cameraOpen && (
        <CameraCapture
          open
          outputFormat="pdf"
          onClose={() => setCameraOpen(false)}
          onCapture={(photo) => {
            setCameraOpen(false);
            selectFile(photo);
          }}
          onFallbackImport={() => {
            setCameraOpen(false);
            fileInputRef.current?.click();
          }}
        />
      )}
      {preview && !cameraOpen && (
        <PatientArchivePreview
          key={stored?.id ?? file?.name}
          patientId={patientId}
          operatorId={operatorId}
          operatorRole={operatorRole}
          document={stored ?? undefined}
          file={file}
          title={DOCUMENT_TYPE_LABELS[form.tipo]}
          onClose={() => setPreview(false)}
        />
      )}
    </div>
  );
}

