import { useEffect, useMemo, useRef, useState } from 'react';
import type { CartellaPaziente, DocumentoConsegnato, Paziente } from '../../../types';
import {
  ARCHIVE_CATEGORIES,
  buildDocumentArchive,
  filterDocumentArchive,
  archiveFolderLabel,
  archiveEntryTypeLabel,
  type ArchiveFolder,
  type ArchiveStatus,
  type ArchiveEntry,
} from '../../../lib/patientDocumentArchive';
import { useDocumentArchive } from '../../../lib/useDocumentArchive';
import { ClinicalTableSection, fmtDate } from './shared';
import { archivePrintUnavailable, selectedArchiveDocuments } from '../../../lib/archivePrint';
import type { PatientDocumentMeta } from '../../../lib/patientDocumentsPage';
import { ArchivePrintDialog } from './ArchivePrintDialog';
import { ArchiveDocumentForm, DOCUMENT_STATUS_LABELS } from './ArchiveDocumentForm';
import { PatientArchivePreview } from './PatientArchivePreview';
import { ConfirmDialog } from '../../shared/ConfirmDialog';
import { PatientArchiveTree } from './PatientArchiveTree';
import './PatientDocumentArchive.css';
import './PatientArchiveTree.css';
import { formatFacilityLocalMinute } from '../../../lib/facilityTime';
import type { AssessmentTarget, AssessmentType } from '../../../lib/assessments/assessmentTypes';

interface Props {
  cartella: CartellaPaziente;
  paziente: Paziente;
  onUpdate: (updates: Partial<CartellaPaziente>) => void | Promise<boolean>;
  operatoreNome: string;
  operatoreId?: string;
  operatoreRole?: string;
  focusDocumentId?: string;
  expectedAssessmentId?: string;
  expectedAssessmentType?: AssessmentType;
  onOpenAssessment?: (assessment: AssessmentTarget) => void;
}

export function DocumentiTab(props: Props) {
  return (
    <DocumentArchiveWorkspace
      key={`${props.paziente.id}|${props.operatoreId}|${props.operatoreRole}`}
      {...props}
    />
  );
}

function DocumentArchiveWorkspace({
  cartella,
  paziente,
  onUpdate,
  operatoreNome,
  operatoreId,
  operatoreRole,
  focusDocumentId,
  expectedAssessmentId,
  expectedAssessmentType,
  onOpenAssessment,
}: Props) {
  const archive = useDocumentArchive(paziente.id, operatoreId, operatoreRole);
  const records = cartella.documentiConsegnati ?? [];
  const entries = useMemo(
    () => buildDocumentArchive(records, archive.documents),
    [records, archive.documents],
  );
  const [folder, setFolder] = useState<ArchiveFolder>({ category: 'tutti' });
  const [query, setQuery] = useState('');
  const [archived, setArchived] = useState<ArchiveStatus>('tutti');
  const [visible, setVisible] = useState(25);
  const [form, setForm] = useState<{ key: string; entry: ArchiveEntry | null } | null>(null);
  const [preview, setPreview] = useState<ArchiveEntry | null>(null);
  const [removing, setRemoving] = useState<ArchiveEntry | null>(null);
  const [saving, setSaving] = useState(false);
  const busy = useRef(false);
  const alive = useRef(true);
  const [error, setError] = useState('');
  const [selected, setSelected] = useState<Set<string>>(() => new Set());
  const [printDocuments, setPrintDocuments] = useState<PatientDocumentMeta[] | null>(null);
  const selectAllRef = useRef<HTMLInputElement>(null);
  useEffect(() => {
    alive.current = true;
    return () => {
      alive.current = false;
    };
  }, []);
  const filtered = filterDocumentArchive(entries, folder.category, query, archived, folder.type, folder.assessmentType);
  const folderEntries = filterDocumentArchive(entries, 'tutti', query, archived);
  const selectFolder = (next: ArchiveFolder) => {
    setFolder(next);
    setVisible(25);
  };
  const selectedCategory = ARCHIVE_CATEGORIES.find((item) => item.id === folder.category);
  const complete = archive.status === 'ready';
  const focusedDocument = useRef('');
  useEffect(() => {
    const focusKey = `${focusDocumentId}:${expectedAssessmentId}:${expectedAssessmentType}`;
    if (!complete || !focusDocumentId || focusedDocument.current === focusKey) return;
    const timer = window.setTimeout(() => {
      focusedDocument.current = focusKey;
      const entry = entries.find(item => item.document?.id === focusDocumentId);
      if (!entry || (expectedAssessmentId && entry.document?.assessment?.id !== expectedAssessmentId) || (expectedAssessmentType && entry.document?.assessment?.type !== expectedAssessmentType)) setError('Documento della valutazione non disponibile nell’archivio corrente.');
      else setPreview(entry);
    }, 0);
    return () => window.clearTimeout(timer);
  }, [complete, entries, focusDocumentId, expectedAssessmentId, expectedAssessmentType]);
  const selectedDocuments = selectedArchiveDocuments(entries, selected);
  const visibleDocuments = selectedArchiveDocuments(
    filtered.slice(0, visible),
    new Set(entries.flatMap((entry) => entry.document ? [entry.document.id] : [])),
  );
  const visibleSelected = visibleDocuments.filter((document) => selected.has(document.id)).length;
  const allVisibleSelected = visibleDocuments.length > 0 && visibleSelected === visibleDocuments.length;
  const hiddenSelected = selectedDocuments.length - visibleSelected;
  useEffect(() => {
    if (selectAllRef.current) selectAllRef.current.indeterminate = visibleSelected > 0 && !allVisibleSelected;
  }, [visibleSelected, allVisibleSelected]);
  useEffect(() => {
    if (complete) setSelected((current) => {
      const existing = new Set(entries.flatMap((entry) => entry.document ? [entry.document.id] : []));
      const next = new Set([...current].filter((id) => existing.has(id)));
      return next.size === current.size ? current : next;
    });
  }, [entries, complete]);
  function toggleSelected(id: string) {
    setSelected((current) => {
      const next = new Set(current);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  }
  const openForm = (entry: ArchiveEntry | null) => {
    setError('');
    setForm({ key: crypto.randomUUID(), entry });
  };
  async function update(recordsToSave: DocumentoConsegnato[]) {
    if (busy.current || form) return;
    busy.current = true;
    setSaving(true);
    setError('');
    try {
      const ok = await onUpdate({ documentiConsegnati: recordsToSave });
      if (ok === false) throw new Error('Salvataggio non riuscito. Riprova.');
      if (alive.current) setRemoving(null);
    } catch {
      if (alive.current) setError('Salvataggio non riuscito. Riprova.');
    } finally {
      busy.current = false;
      if (alive.current) setSaving(false);
    }
  }
  return (
    <div className="cr-tab-content patient-document-archive">
      <div className="print-only print-form-header">
        <div className="print-form-header__title">ARCHIVIO DOCUMENTI</div>
        <div>
          {paziente.lastName} {paziente.firstName}
        </div>
      </div>
      <ClinicalTableSection
        title="Documenti paziente"
        count={complete ? entries.length : undefined}
        countLabel="documenti"
        actions={
          <>
            <button
              type="button"
              className="btn-secondary btn-sm no-print"
              disabled={!complete || !selectedDocuments.length || !!form || saving || !!printDocuments}
              onClick={() => setPrintDocuments(selectedDocuments)}
            >
              Stampa selezionati ({selectedDocuments.length})
            </button>
            <button
              type="button"
              className="btn-sm"
              disabled={!complete || !!form || saving || folder.category === 'valutazioni'}
              onClick={() => openForm(null)}
            >
              + Aggiungi
            </button>
          </>
        }
      >
        <div className="cts__body--padded">
          {form && (
            <ArchiveDocumentForm
              key={form.key}
              initial={form.entry}
              defaultType={folder.type ?? selectedCategory?.types[0]}
              records={records}
              patientId={paziente.id}
              operatorId={operatoreId}
              operatorRole={operatoreRole}
              operatorName={operatoreNome}
              onPersist={(next) => onUpdate({ documentiConsegnati: next })}
              onStored={archive.remember}
              onClose={() => setForm(null)}
            />
          )}
          <div className="patient-document-archive__filters no-print">
            <label>
              Cerca nell’archivio
              <input
                className="form-input"
                type="search"
                maxLength={120}
                placeholder="Descrizione, nome file, provenienza…"
                value={query}
                onChange={(event) => {
                  setQuery(event.target.value);
                  setVisible(25);
                }}
              />
            </label>
            <label>
              Mostra
              <select
                className="form-input"
                value={archived === 'tutti' ? 'tutti' : archived ? 'archiviati' : 'correnti'}
                onChange={(event) => {
                  setArchived(
                    event.target.value === 'tutti' ? 'tutti' : event.target.value === 'archiviati',
                  );
                  setVisible(25);
                }}
              >
                <option value="tutti">Tutti i documenti</option>
                <option value="correnti">Documenti correnti</option>
                <option value="archiviati">Documenti nello storico</option>
              </select>
            </label>
            <button
              type="button"
              className="btn-secondary btn-sm"
              disabled={archive.status === 'loading' || !!form || saving}
              onClick={archive.reload}
            >
              Aggiorna archivio
            </button>
          </div>
          <p className="patient-document-archive__intro">
            Qui trovi tutti i file e le foto salvati per il paziente, anche da esami, medicazioni e
            importazioni.
          </p>
          <div className="patient-document-archive__selection no-print">
            <label>
              <input ref={selectAllRef} type="checkbox" checked={allVisibleSelected}
                disabled={!complete || !visibleDocuments.length}
                onChange={() => setSelected((current) => {
                  const next = new Set(current);
                  for (const document of visibleDocuments)
                    if (allVisibleSelected) next.delete(document.id); else next.add(document.id);
                  return next;
                })} />
              Seleziona documenti visibili
            </label>
            <span role="status">{selectedDocuments.length} selezionati{hiddenSelected > 0 ? ` · ${hiddenSelected} non visibili in questo elenco` : ''}</span>
            {selected.size > 0 && <button type="button" className="btn-secondary btn-sm" onClick={() => setSelected(new Set())}>Deseleziona tutti</button>}
          </div>
          <div className="patient-document-archive__workspace">
            <PatientArchiveTree
              entries={folderEntries}
              selected={folder}
              complete={complete}
              onSelect={selectFolder}
            />
            <section
              className="patient-document-archive__results"
              aria-label="Contenuto della cartella"
            >
              <nav className="patient-document-archive__path" aria-label="Percorso documenti">
                <button type="button" onClick={() => selectFolder({ category: 'tutti' })}>
                  Documenti
                </button>
                {selectedCategory && (
                  <>
                    <span aria-hidden="true">/</span>
                    <button
                      type="button"
                      onClick={() => selectFolder({ category: selectedCategory.id })}
                    >
                      {selectedCategory.label}
                    </button>
                  </>
                )}
                {folder.type && (
                  <>
                    <span aria-hidden="true">/</span>
                    <span aria-current="location">{archiveFolderLabel(folder)}</span>
                  </>
                )}
              </nav>
              <h3 className="patient-document-archive__folder-title">
                {archiveFolderLabel(folder)}
              </h3>
              {archive.status === 'loading' && (
                <p role="status">Caricamento dell’archivio completo…</p>
              )}
              {archive.status === 'error' && (
                <div className="patient-archive__error" role="alert">
                  <p>
                    Impossibile caricare tutti i file. Le schede visibili sono un elenco parziale.
                  </p>
                  <button
                    type="button"
                    className="btn-secondary btn-sm"
                    disabled={!!form || saving}
                    onClick={archive.reload}
                  >
                    Riprova archivio
                  </button>
                </div>
              )}
              {error && (
                <p role="alert" className="patient-archive__error">
                  {error}
                </p>
              )}
              {complete && (
                <p className="patient-document-archive__summary" role="status">
                  {filtered.length}{' '}
                  {filtered.length === 1 ? 'documento trovato' : 'documenti trovati'}
                </p>
              )}
              {complete && filtered.length === 0 && (
                <p className="cr-empty">
                  {query || folder.category !== 'tutti'
                    ? 'Nessun documento corrisponde alla ricerca.'
                    : 'Nessun documento in questa cartella.'}
                </p>
              )}
              {archive.status !== 'loading' && (
                <ul className="patient-document-archive__list">
                  {filtered.slice(0, visible).map((entry) => (
                    <li key={entry.id} className="patient-document-archive__item">
                      <div className="patient-document-archive__file-icon" aria-hidden="true">
                        <svg
                          viewBox="0 0 24 24"
                          fill="none"
                          stroke="currentColor"
                          strokeWidth="1.6"
                        >
                          <path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z" />
                          <path d="M14 3v6h6M8 13h8M8 17h6" />
                        </svg>
                      </div>
                      <div className="patient-document-archive__details">
                        <label className="patient-document-archive__print-option no-print">
                          <input type="checkbox"
                            checked={!!entry.document && selected.has(entry.document.id)}
                            disabled={!complete || !!archivePrintUnavailable(entry)}
                            onChange={() => entry.document && toggleSelected(entry.document.id)}
                            aria-label={`Seleziona per la stampa: ${entry.title}`} />
                          {archivePrintUnavailable(entry) || 'Seleziona per la stampa'}
                        </label>
                        <button
                          type="button"
                          className="patient-document-archive__title"
                          onClick={() => setPreview(entry)}
                        >
                          {entry.title}
                        </button>
                        <div className="patient-document-archive__meta">
                          <span className="badge badge--blue">
                            {archiveEntryTypeLabel(entry)}
                          </span>
                          {entry.archived && <span className="badge">Storico</span>}
                          <span>{fmtDate(entry.date)}</span>
                          <span>
                            {DOCUMENT_STATUS_LABELS[entry.record?.stato ?? 'ricevuto'] ??
                              'Da verificare'}
                          </span>
                        </div>
                        {entry.document ? (
                          <p>
                            {entry.document.originalName} ·{' '}
                            {(entry.document.sizeBytes / 1024 / 1024).toFixed(1)} MB
                          </p>
                        ) : (
                          <p>
                            {entry.unavailable
                              ? 'Allegato non disponibile'
                              : 'Nessun file allegato'}
                          </p>
                        )}
                        {entry.document?.assessment && <p>Valutata {formatFacilityLocalMinute(entry.document.assessment.assessedAt)} · Registrata {formatFacilityLocalMinute(entry.document.createdAt)}</p>}
                        {entry.record?.provenienza && (
                          <p>Provenienza: {entry.record.provenienza}</p>
                        )}
                        {entry.record?.scadenza && (
                          <p>Scadenza: {fmtDate(entry.record.scadenza)}</p>
                        )}
                        {entry.record?.firmatoDA && entry.record.firmatoDA !== 'non_firmato' && (
                          <p>Firmato da: {entry.record.firmatoDA}</p>
                        )}
                        {entry.record?.operatore && <p>Registrato da: {entry.record.operatore}</p>}
                        {entry.record?.note && (
                          <p className="patient-document-archive__notes">{entry.record.note}</p>
                        )}
                      </div>
                      <div className="patient-document-archive__actions no-print">
                        <button
                          type="button"
                          className="btn-secondary btn-sm"
                          onClick={() => setPreview(entry)}
                        >
                          {entry.document ? 'Visualizza' : 'Dettagli'}
                        </button>
                        {entry.document?.assessment ? <button type="button" className="btn-secondary btn-sm" disabled={!onOpenAssessment} onClick={() => onOpenAssessment?.({ id: entry.document!.assessment!.id, type: entry.document!.assessment!.type })}>Apri valutazione</button> : <button
                          type="button"
                          className="btn-secondary btn-sm"
                          disabled={!complete || !!form || saving}
                          onClick={() => openForm(entry)}
                        >
                          Modifica dettagli
                        </button>}
                        {entry.record && !entry.document?.assessment && (
                          <button
                            type="button"
                            className="patient-document-archive__remove"
                            disabled={!complete || !!form || saving}
                            onClick={() => setRemoving(entry)}
                          >
                            Rimuovi scheda
                          </button>
                        )}
                      </div>
                    </li>
                  ))}
                </ul>
              )}
              {filtered.length > visible && (
                <button
                  type="button"
                  className="btn-secondary btn-sm no-print"
                  onClick={() => setVisible((value) => value + 25)}
                >
                  Mostra altri documenti ({visible} di {filtered.length})
                </button>
              )}
            </section>
          </div>
        </div>
      </ClinicalTableSection>
      {preview && (
        <PatientArchivePreview
          key={preview.id}
          patientId={paziente.id}
          operatorId={operatoreId}
          operatorRole={operatoreRole}
          document={preview.document}
          title={preview.title}
          unavailable={preview.unavailable}
          onClose={() => setPreview(null)}
        />
      )}
      {printDocuments && <ArchivePrintDialog
        documents={printDocuments} patientId={paziente.id}
        operatorId={operatoreId} operatorRole={operatoreRole}
        onClose={() => setPrintDocuments(null)}
      />}
      {removing && (
        <ConfirmDialog
          open
          title="Rimuovi scheda documento"
          message={
            removing.document
              ? 'Rimuovere i dettagli della scheda? Il file originale rimane nell’archivio.'
              : 'Rimuovere questa registrazione?'
          }
          confirmLabel="Rimuovi scheda"
          onConfirm={() =>
            void update(records.filter((record) => record.id !== removing.record?.id))
          }
          onCancel={() => setRemoving(null)}
        />
      )}
    </div>
  );
}

import { useMemo, useState } from 'react';
import { ClinicalAttachments as SectionPhotos } from './ClinicalAttachments';
import type { CartellaPaziente, EsameClinicoRecord, Paziente } from '../../../types';
import {
  uid,
  todayStr,
  nowISO,
  fmtDate,
  ClinicalTableSection,
  InlineForm,
  EmptyState,
} from './shared';
import { usePatientDocuments } from '../../../lib/usePatientDocuments';
import type { PatientDocumentMeta } from '../../../lib/patientDocumentsPage';
import { LoadErrorState } from './LoadErrorState';

type SectionDocMeta = PatientDocumentMeta;

interface Props {
  cartella: CartellaPaziente;
  paziente: Paziente;
  onUpdate: (updates: Partial<CartellaPaziente>) => void;
  operatoreNome: string;
  operatoreId?: string;
  operatoreRole?: string;
}

// ── Sort helper: chronological descending (most recent first) ────────────────

export function sortEsamiDesc(records: EsameClinicoRecord[]): EsameClinicoRecord[] {
  return [...records].sort((a, b) => {
    const da = `${a.data}${a.ora ? 'T' + a.ora : 'T00:00'}`;
    const db = `${b.data}${b.ora ? 'T' + b.ora : 'T00:00'}`;
    return db.localeCompare(da);
  });
}

// ── Empty form factory ───────────────────────────────────────────────────────

function emptyForm(): Omit<EsameClinicoRecord, 'id' | 'operatore' | 'createdAt'> {
  return { data: todayStr(), ora: '', descrizione: '', esito: '', allegati: '', note: '' };
}

// ── Single row display ───────────────────────────────────────────────────────

function EsameRow({
  r,
  onEdit,
  onDelete,
}: {
  r: EsameClinicoRecord;
  onEdit: () => void;
  onDelete: () => void;
}) {
  return (
    <div className="cr-item-row">
      <div className="cr-item-body">
        <div className="cr-visita-header">
          <span className="cr-visita-tipo">{r.descrizione}</span>
          <span className="cr-diag-meta">
            {fmtDate(r.data)}
            {r.ora ? ` ${r.ora}` : ''} · {r.operatore}
          </span>
        </div>
        {r.esito && <p className="cr-nota-text">{r.esito}</p>}
        {r.allegati && <p className="cr-diag-note">Allegati: {r.allegati}</p>}
        {r.note && <p className="cr-diag-note">{r.note}</p>}
      </div>
      <div className="cr-item-actions">
        <button className="icon-btn icon-btn--sm icon-btn--edit" title="Modifica" onClick={onEdit}>
          <svg
            width="14"
            height="14"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7" />
            <path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z" />
          </svg>
        </button>
        <button
          className="icon-btn icon-btn--sm icon-btn--danger"
          title="Elimina"
          onClick={onDelete}
        >
          <svg
            width="14"
            height="14"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <polyline points="3 6 5 6 21 6" />
            <path d="M19 6l-1 14H6L5 6" />
            <path d="M10 11v6" />
            <path d="M14 11v6" />
            <path d="M9 6V4h6v2" />
          </svg>
        </button>
      </div>
    </div>
  );
}

// ── Inline add/edit form ─────────────────────────────────────────────────────

function EsameForm({
  initial,
  onSave,
  onCancel,
}: {
  initial: Omit<EsameClinicoRecord, 'id' | 'operatore' | 'createdAt'>;
  onSave: (data: Omit<EsameClinicoRecord, 'id' | 'operatore' | 'createdAt'>) => void;
  onCancel: () => void;
}) {
  const [f, setF] = useState(initial);
  const set = <K extends keyof typeof f>(k: K, v: (typeof f)[K]) => setF((p) => ({ ...p, [k]: v }));

  return (
    <InlineForm onSave={() => onSave(f)} onCancel={onCancel}>
      <div className="op-form-grid">
        <div className="form-field">
          <label className="form-label">Descrizione *</label>
          <input
            className="form-input"
            value={f.descrizione}
            placeholder="es. Emocromo completo, RX torace…"
            onChange={(e) => set('descrizione', e.target.value)}
          />
        </div>
        <div className="form-field">
          <label className="form-label">Data</label>
          <input
            className="form-input"
            type="date"
            value={f.data}
            onChange={(e) => set('data', e.target.value)}
          />
        </div>
        <div className="form-field">
          <label className="form-label">Ora (facoltativo)</label>
          <input
            className="form-input"
            type="time"
            value={f.ora ?? ''}
            onChange={(e) => set('ora', e.target.value)}
          />
        </div>
      </div>
      <div className="form-field" style={{ marginTop: 8 }}>
        <label className="form-label">Esito / Referto</label>
        <textarea
          className="form-input"
          rows={3}
          value={f.esito}
          onChange={(e) => set('esito', e.target.value)}
        />
      </div>
      <div className="form-field" style={{ marginTop: 8 }}>
        <label className="form-label">Allegati (nomi file / riferimenti)</label>
        <input
          className="form-input"
          value={f.allegati ?? ''}
          onChange={(e) => set('allegati', e.target.value)}
        />
      </div>
      <div className="form-field" style={{ marginTop: 8 }}>
        <label className="form-label">Note (facoltativo)</label>
        <textarea
          className="form-input"
          rows={2}
          value={f.note ?? ''}
          onChange={(e) => set('note', e.target.value)}
        />
      </div>
    </InlineForm>
  );
}

// ── Reusable section (one of three) ──────────────────────────────────────────

function EsameSection({
  title,
  emptyMsg,
  list,
  operatoreNome,
  onChange,
}: {
  title: string;
  emptyMsg: string;
  list: EsameClinicoRecord[];
  operatoreNome: string;
  onChange: (updated: EsameClinicoRecord[]) => void;
}) {
  const [showAdd, setShowAdd] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Omit<
    EsameClinicoRecord,
    'id' | 'operatore' | 'createdAt'
  > | null>(null);

  const sorted = sortEsamiDesc(list);

  function handleAdd(data: Omit<EsameClinicoRecord, 'id' | 'operatore' | 'createdAt'>) {
    if (!data.descrizione.trim()) return;
    const rec: EsameClinicoRecord = {
      ...data,
      id: uid(),
      operatore: operatoreNome,
      createdAt: nowISO(),
    };
    onChange([...list, rec]);
    setShowAdd(false);
  }

  function handleUpdate(
    id: string,
    data: Omit<EsameClinicoRecord, 'id' | 'operatore' | 'createdAt'>,
  ) {
    onChange(list.map((r) => (r.id === id ? { ...r, ...data } : r)));
    setEditId(null);
    setEditForm(null);
  }

  function handleDelete(id: string) {
    onChange(list.filter((r) => r.id !== id));
  }

  return (
    <ClinicalTableSection
      title={title}
      count={list.length}
      countLabel={list.length === 1 ? 'elemento' : 'elementi'}
      actions={
        <button
          className="btn-sm"
          onClick={() => {
            setShowAdd((v) => !v);
            setEditId(null);
            setEditForm(null);
          }}
        >
          + Aggiungi
        </button>
      }
    >
      <div className="cts__body--padded">
        {showAdd && (
          <EsameForm initial={emptyForm()} onSave={handleAdd} onCancel={() => setShowAdd(false)} />
        )}
        <div className="cr-list">
          {sorted.length === 0 && <EmptyState msg={emptyMsg} />}
          {sorted.map((r) =>
            editId === r.id && editForm ? (
              <EsameForm
                key={r.id}
                initial={editForm}
                onSave={(data) => handleUpdate(r.id, data)}
                onCancel={() => {
                  setEditId(null);
                  setEditForm(null);
                }}
              />
            ) : (
              <EsameRow
                key={r.id}
                r={r}
                onEdit={() => {
                  setEditId(r.id);
                  setEditForm({
                    data: r.data,
                    ora: r.ora,
                    descrizione: r.descrizione,
                    esito: r.esito,
                    allegati: r.allegati,
                    note: r.note,
                  });
                  setShowAdd(false);
                }}
                onDelete={() => handleDelete(r.id)}
              />
            ),
          )}
        </div>
      </div>
    </ClinicalTableSection>
  );
}

// ── Main tab component ────────────────────────────────────────────────────────

export function EsamiConsulenzeTab({
  cartella,
  paziente,
  onUpdate,
  operatoreNome,
  operatoreId,
  operatoreRole,
}: Props) {
  const {
    documents,
    status: documentStatus,
    loadingMore,
    loadMoreError,
    pageInfo,
    reload: reloadDocuments,
    loadMore,
    upsertDocument,
  } = usePatientDocuments({
    patientId: paziente.id,
    operatorId: operatoreId,
    operatorRole: operatoreRole,
  });

  const documentsByType = useMemo(() => {
    const grouped: Record<'esame' | 'rx' | 'consulenza', SectionDocMeta[]> = {
      esame: [],
      rx: [],
      consulenza: [],
    };
    for (const document of documents) {
      if (Object.hasOwn(grouped, document.documentType)) {
        grouped[document.documentType as keyof typeof grouped].push(document);
      }
    }
    return grouped;
  }, [documents]);

  return (
    <div className="cr-tab-content">
      <div style={{ marginBottom: 8 }}>
        <h3 className="cr-tab-title" style={{ margin: 0 }}>
          Esami &amp; Consulenze
        </h3>
        <p style={{ margin: '4px 0 16px', fontSize: 13, color: '#667085' }}>
          Le tre sezioni sono indipendenti — i dati non sono mescolati.
        </p>
      </div>

      {documentStatus === 'loading' && (
        <p role="status" style={{ margin: '0 0 12px', color: 'var(--c-muted, #667085)' }}>
          Caricamento allegati…
        </p>
      )}
      {documentStatus === 'error' && (
        <LoadErrorState
          message="Impossibile caricare gli allegati: l’elenco potrebbe essere incompleto."
          onRetry={reloadDocuments}
          retryLabel="Riprova allegati"
        />
      )}
      {loadMoreError && (
        <LoadErrorState
          message={`${loadMoreError} L’elenco allegati mostrato è parziale.`}
          onRetry={loadMore}
          retryLabel="Riprova caricamento"
        />
      )}

      <EsameSection
        title="Esami ematici"
        emptyMsg="Nessun esame ematico registrato."
        list={cartella.esamiEmatici ?? []}
        operatoreNome={operatoreNome}
        onChange={(updated) => onUpdate({ esamiEmatici: updated })}
      />
      <SectionPhotos
        patientId={paziente.id}
        documentType="esame"
        operatorId={operatoreId}
        operatorRole={operatoreRole}
        documents={documentsByType.esame}
        metadataLoading={documentStatus === 'loading'}
        onDocumentCreated={(document) => (document ? upsertDocument(document) : reloadDocuments())}
      />

      <div style={{ marginTop: 16 }}>
        <EsameSection
          title="RX / Diagnostica per immagini"
          emptyMsg="Nessun esame strumentale / RX registrato."
          list={cartella.esamiStrumentali ?? []}
          operatoreNome={operatoreNome}
          onChange={(updated) => onUpdate({ esamiStrumentali: updated })}
        />
        <SectionPhotos
          patientId={paziente.id}
          documentType="rx"
          operatorId={operatoreId}
          operatorRole={operatoreRole}
          documents={documentsByType.rx}
          metadataLoading={documentStatus === 'loading'}
          onDocumentCreated={(document) =>
            document ? upsertDocument(document) : reloadDocuments()
          }
        />
      </div>
      {pageInfo.hasMore && !loadMoreError && (
        <div className="empty-state-card" role="status" aria-live="polite">
          <p>Sono mostrati i primi {documents.length} allegati.</p>
          <button
            type="button"
            className="btn-secondary btn-sm"
            onClick={loadMore}
            disabled={loadingMore}
          >
            {loadingMore ? 'Caricamento…' : 'Carica altri allegati'}
          </button>
        </div>
      )}

      <div style={{ marginTop: 16 }}>
        <EsameSection
          title="Consulenze specialistiche"
          emptyMsg="Nessuna consulenza specialistica registrata."
          list={cartella.consulenze ?? []}
          operatoreNome={operatoreNome}
          onChange={(updated) => onUpdate({ consulenze: updated })}
        />
        <SectionPhotos
          patientId={paziente.id}
          documentType="consulenza"
          operatorId={operatoreId}
          operatorRole={operatoreRole}
          documents={documentsByType.consulenza}
          metadataLoading={documentStatus === 'loading'}
          onDocumentCreated={(document) =>
            document ? upsertDocument(document) : reloadDocuments()
          }
        />
      </div>
    </div>
  );
}

