import * as React from 'react';
import type { Segment } from './segments';
import { sectionMarkdownBlocks, type TextRange } from './sectionMarkdown';
import './FormattedSectionText.css';

interface IndexedSegment extends Segment, TextRange {}

/** Match validated semantic segments to source ranges after hiding only supported
 * Markdown delimiters. Binary lookup avoids scanning all tags for every paragraph. */
export function FormattedSectionText({ rawText, segments }: { rawText: string; segments: Segment[] }) {
  let offset = 0;
  const indexed: IndexedSegment[] = segments.map((segment) => {
    const start = offset;
    offset += segment.text.length;
    return { ...segment, start, end: offset };
  });

  function range(start: number, end: number): React.ReactNode[] {
    let low = 0;
    let high = indexed.length;
    while (low < high) {
      const mid = (low + high) >>> 1;
      if (indexed[mid].end <= start) low = mid + 1;
      else high = mid;
    }
    const nodes: React.ReactNode[] = [];
    for (let i = low; i < indexed.length && indexed[i].start < end; i++) {
      const segment = indexed[i];
      const text = rawText.slice(Math.max(start, segment.start), Math.min(end, segment.end));
      nodes.push(segment.bold
        ? <strong key={i} className={segment.className}>{text}</strong>
        : segment.illegible
          ? <mark key={i} className="stt-illegible">{text}</mark>
          : <span key={i}>{text}</span>);
    }
    return nodes;
  }

  function inline({ start, end }: TextRange): React.ReactNode[] {
    const nodes: React.ReactNode[] = [];
    let cursor = start;
    for (const match of rawText.slice(start, end).matchAll(/\*\*([^*\r\n]+)\*\*/g)) {
      const at = start + match.index;
      if (at > cursor) nodes.push(<React.Fragment key={cursor}>{range(cursor, at)}</React.Fragment>);
      nodes.push(<strong key={at}>{range(at + 2, at + match[0].length - 2)}</strong>);
      cursor = at + match[0].length;
    }
    if (cursor < end) nodes.push(<React.Fragment key={cursor}>{range(cursor, end)}</React.Fragment>);
    return nodes;
  }

  return (
    <div className="section-markdown">
      {sectionMarkdownBlocks(rawText).map((block, index) => {
        if (block.kind === 'heading') {
          const Heading = block.level === 1 ? 'h4' : block.level === 2 ? 'h5' : 'h6';
          return <Heading key={index}>{inline(block)}</Heading>;
        }
        if (block.kind === 'paragraph') return <p key={index}>{inline(block)}</p>;
        if (block.kind === 'literal') return <p key={index}>{range(block.start, block.end)}</p>;
        const List = block.ordered ? 'ol' : 'ul';
        return (
          <List key={index} className={block.ordered ? 'section-markdown__numbered' : undefined}>
            {block.items.map((item) => (
              <li key={item.start}>
                {block.ordered && <span className="section-markdown__number">{item.marker}</span>}
                <div>{inline(item)}</div>
              </li>
            ))}
          </List>
        );
      })}
    </div>
  );
}

export interface TextRange { start: number; end: number }
export interface ListItemRange extends TextRange { marker: string }
export type MarkdownBlock =
  | ({ kind: 'paragraph' } & TextRange)
  | ({ kind: 'literal' } & TextRange)
  | ({ kind: 'heading'; level: number } & TextRange)
  | { kind: 'list'; ordered: boolean; items: ListItemRange[] };

/** Structural ranges into the unmodified source: never normalize line endings or
 * rewrite clinical content before applying semantic annotation offsets. */
export function sectionMarkdownBlocks(raw: string): MarkdownBlock[] {
  const blocks: MarkdownBlock[] = [];
  let paragraph: (TextRange & { kind: 'paragraph' | 'literal' }) | undefined;
  let list: Extract<MarkdownBlock, { kind: 'list' }> | undefined;
  let fence: { marker: string; size: number; block: TextRange } | undefined;

  for (const match of raw.matchAll(/([^\r\n]*)(\r\n|\r|\n|$)/g)) {
    if (!match[0]) break;
    const line = match[1];
    const start = match.index;
    const end = start + line.length;
    if (fence) {
      fence.block.end = end;
      const closing = line.trim();
      if (closing.length >= fence.size && [...closing].every((char) => char === fence!.marker)) {
        fence = undefined;
      }
      continue;
    }
    const openingFence = line.match(/^[ \t]{0,3}(`{3,}|~{3,})/);
    if (openingFence) {
      const block = { kind: 'literal' as const, start, end };
      blocks.push(block);
      fence = { marker: openingFence[1][0], size: openingFence[1].length, block };
      paragraph = undefined;
      list = undefined;
      continue;
    }
    if (!line.trim()) {
      paragraph = undefined;
      list = undefined;
      continue;
    }
    const heading = line.match(/^[ \t]{0,3}(#{1,6})[ \t]+/);
    if (heading) {
      blocks.push({ kind: 'heading', level: heading[1].length, start: start + heading[0].length, end });
      paragraph = undefined;
      list = undefined;
      continue;
    }

    // A spaced minus before a numeric value is clinical text, not a bullet.
    // A date after a bullet (e.g. - 12/03/2026) is still a list item.
    const datedBullet = /^[ \t]*-[ \t]+\d{1,2}[/.\-]\d{1,2}[/.\-]\d{2,4}\b/.test(line);
    const negativeValue = /^[ \t]*-[ \t]+(?:\d|[.,]\d)/.test(line) && !datedBullet;
    const numbered = line.match(/^[ \t]{0,3}(\d+[.)])[ \t]+/);
    const bullet = !negativeValue && (
      line.match(/^[ \t]{0,3}([-*•])[ \t]+/) ??
      line.match(/^[ \t]{0,3}([-•])(?=\p{L})/u)
    );
    const item = numbered || bullet;
    if (item) {
      const ordered = !!numbered;
      if (!list || list.ordered !== ordered) {
        list = { kind: 'list', ordered, items: [] };
        blocks.push(list);
      }
      list.items.push({ marker: item[1], start: start + item[0].length, end });
      paragraph = undefined;
      continue;
    }
    if (negativeValue || /^[ \t]*---/.test(line)) list = undefined;
    if (list) {
      list.items[list.items.length - 1].end = end;
    } else if (paragraph) {
      paragraph.end = end;
    } else {
      paragraph = { kind: 'paragraph', start, end };
      blocks.push(paragraph);
    }
  }
  return blocks;
}

