import { useEffect, useRef, useState } from 'react';
import type { PreviewDoc } from '../components/shared/DocumentPreview';

export interface UploadOutcome {
  filename: string;
  status: string;
  documentId?: string;
  message?: string;
}
export interface UploadedDocument {
  id: string;
  filename: string;
  mimeType: string;
  logicalDoc?: string | null;
}

export function isImportPhotoReplacement(files: File[]): boolean {
  return (
    files.length === 1 &&
    (files[0].type.startsWith('image/') || files[0].type === 'application/pdf')
  );
}

// The upload API returns one outcome per input, in input order. Filenames are not unique.
export class ImportPreviewSession {
  generation = 0;
  documents: PreviewDoc[] = [];

  accept(files: File[], outcomes: UploadOutcome[], documents: UploadedDocument[]) {
    if (files.length !== outcomes.length) return [];
    const added: PreviewDoc[] = [];
    outcomes.forEach((outcome, index) => {
      if (outcome.status !== 'accepted' || !outcome.documentId) return;
      const doc = documents.find((d) => d.id === outcome.documentId);
      if (!doc || [...this.documents, ...added].some((p) => p.id === doc.id)) return;
      const f = files[index];
      added.push({
        id: doc.id,
        name: doc.filename,
        type: doc.mimeType,
        url: URL.createObjectURL(f),
      });
    });
    this.documents = [...this.documents, ...added];
    return added;
  }

  remove(id: string) {
    this.documents.filter((p) => p.id === id).forEach((p) => URL.revokeObjectURL(p.url));
    this.documents = this.documents.filter((p) => p.id !== id);
  }

  clear() {
    this.documents.forEach((p) => URL.revokeObjectURL(p.url));
    this.documents = [];
    this.generation++;
  }
}

export function useImportPreviews(open: boolean) {
  const session = useRef(new ImportPreviewSession()).current;
  const [previews, setPreviews] = useState<PreviewDoc[]>([]);
  useEffect(() => {
    // Closing the import discards session-only documents; cleanup also covers unmounts.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    if (!open) setPreviews([]);
    return () => session.clear();
  }, [open, session]);
  return {
    previews,
    session,
    acceptFiles(files: File[], outcomes: UploadOutcome[], documents: UploadedDocument[]) {
      const added = session.accept(files, outcomes, documents);
      setPreviews(session.documents);
      return added;
    },
    removePreview(id: string) {
      session.remove(id);
      setPreviews(session.documents);
    },
  };
}

/** Called only after a replacement upload is accepted. Retain the original on any failure. */
export async function finishPhotoReplacement<T extends { documents: UploadedDocument[] }>(
  baseUrl: string,
  job: T,
  originalId: string,
  replacementId: string,
  request: (url: string, options: RequestInit) => Promise<Response>,
  onUpdate: (job: T) => void,
  isCurrent: () => boolean,
): Promise<boolean> {
  const original = job.documents.find((d) => d.id === originalId);
  if (
    !original ||
    originalId === replacementId ||
    !job.documents.some((d) => d.id === replacementId)
  )
    return false;
  const send = async (path: string, method: string, body?: unknown) => {
    if (!isCurrent()) throw new Error('Import session closed');
    const res = await request(`${baseUrl}${path}`, {
      method,
      ...(body === undefined
        ? {}
        : { headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }),
    });
    if (!res.ok) throw new Error('Photo replacement failed');
    const updated = (await res.json()) as T;
    if (!isCurrent()) throw new Error('Import session closed');
    onUpdate(updated);
  };
  if (original.logicalDoc)
    await send(`/files/${replacementId}/logical`, 'POST', { logicalDoc: original.logicalDoc });
  const order = job.documents
    .filter((d) => d.id !== replacementId)
    .flatMap((d) => (d.id === originalId ? [replacementId, originalId] : [d.id]));
  await send('/reorder', 'POST', { order });
  await send(`/files/${originalId}`, 'DELETE');
  return true;
}

export const PATIENT_PHONE_MAX_LENGTH = 40;

export type PatientPhoneResult = { ok: true; phone: string } | { ok: false; error: string };

/** Preserve country prefixes, leading zeroes and familiar display separators. */
export function validatePatientPhone(value: unknown): PatientPhoneResult {
  if (value == null || (typeof value === 'string' && !value.trim())) {
    return { ok: false, error: 'Il telefono è obbligatorio.' };
  }
  if (typeof value === 'string') {
    const phone = value.trim();
    const digits = phone.replace(/\D/g, '').length;
    if (
      phone.length <= PATIENT_PHONE_MAX_LENGTH &&
      /^\+?[\d ()./\-]+$/.test(phone) &&
      digits >= 5 &&
      digits <= 15
    ) {
      return { ok: true, phone };
    }
  }
  return {
    ok: false,
    error: 'Inserisci un telefono valido, con 5–15 cifre e prefisso facoltativo.',
  };
}

import workerUrl from 'pdfjs-dist/build/pdf.worker.min.mjs?url';
import type { RenderedPrintPage } from './archivePrint';

function canvasSize(width: number, height: number, scale = 1) {
  if (![width, height].every((size) => Number.isFinite(size) && size > 0))
    throw new Error('Dimensioni del documento non valide.');
  const fit = Math.min(scale, Math.sqrt(2_200_000 / (width * height)), 4096 / width, 4096 / height);
  return { width: Math.max(1, Math.floor(width * fit)), height: Math.max(1, Math.floor(height * fit)), scale: fit };
}

async function pageBlob(canvas: HTMLCanvasElement, signal: AbortSignal): Promise<RenderedPrintPage> {
  const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, 'image/png'));
  signal.throwIfAborted();
  if (!blob) throw new Error('Impossibile preparare la pagina.');
  return { blob, width: canvas.width, height: canvas.height };
}

export async function* renderArchivePrint(
  blob: Blob, signal: AbortSignal, remainingPages: number,
): AsyncGenerator<RenderedPrintPage> {
  signal.throwIfAborted();
  if (remainingPages < 1) throw new Error('Massimo 40 pagine per ogni stampa.');
  if (blob.type.split(';')[0].trim().toLowerCase() === 'application/pdf') {
    const engine = await import('pdfjs-dist');
    signal.throwIfAborted();
    engine.GlobalWorkerOptions.workerSrc = workerUrl;
    const data = new Uint8Array(await blob.arrayBuffer());
    signal.throwIfAborted();
    const loading = engine.getDocument({ data, stopAtErrors: true });
    const abort = () => { void loading.destroy().catch(() => {}); };
    signal.addEventListener('abort', abort, { once: true });
    try {
      const pdf = await loading.promise;
      signal.throwIfAborted();
      if (pdf.numPages > remainingPages) throw new Error('Massimo 40 pagine per ogni stampa.');
      for (let index = 1; index <= pdf.numPages; index++) {
        const page = await pdf.getPage(index);
        signal.throwIfAborted();
        const natural = page.getViewport({ scale: 1 });
        const size = canvasSize(natural.width, natural.height, 150 / 72);
        const canvas = document.createElement('canvas');
        canvas.width = size.width; canvas.height = size.height;
        const context = canvas.getContext('2d');
        if (!context) throw new Error('Stampa non disponibile nel browser.');
        const render = page.render({ canvas, canvasContext: context,
          viewport: page.getViewport({ scale: size.scale }), intent: 'print', background: '#ffffff' });
        const cancelRender = () => render.cancel();
        signal.addEventListener('abort', cancelRender, { once: true });
        try {
          await render.promise;
          signal.throwIfAborted();
          yield await pageBlob(canvas, signal);
        } finally {
          signal.removeEventListener('abort', cancelRender);
          canvas.width = 0; canvas.height = 0;
          page.cleanup();
        }
      }
    } catch (error) {
      signal.throwIfAborted();
      if (error instanceof Error && error.message.includes('40 pagine')) throw error;
      throw new Error('PDF non leggibile o protetto da password.');
    } finally {
      signal.removeEventListener('abort', abort);
      await loading.destroy().catch(() => {});
    }
    return;
  }
  const url = URL.createObjectURL(blob);
  const image = new Image();
  const abort = () => { image.src = ''; };
  signal.addEventListener('abort', abort, { once: true });
  const canvas = document.createElement('canvas');
  try {
    image.src = url;
    await image.decode();
    signal.throwIfAborted();
    const size = canvasSize(image.naturalWidth, image.naturalHeight);
    canvas.width = size.width; canvas.height = size.height;
    const context = canvas.getContext('2d');
    if (!context) throw new Error('Stampa non disponibile nel browser.');
    context.fillStyle = '#ffffff'; context.fillRect(0, 0, size.width, size.height);
    context.drawImage(image, 0, 0, size.width, size.height);
    yield await pageBlob(canvas, signal);
  } catch {
    signal.throwIfAborted();
    throw new Error('Immagine non leggibile.');
  } finally {
    signal.removeEventListener('abort', abort);
    image.src = ''; URL.revokeObjectURL(url);
    canvas.width = 0; canvas.height = 0;
  }
}

